using RapidRepo.Entities;
using RapidRepo.Entities.Interfaces;

namespace RapidRepo.Testing.Conformance;

/// <summary>
/// A plain entity: no auditing and no soft delete, so <c>Delete</c> removes it permanently. Its key is generated by
/// the store.
/// </summary>
public class Widget : BaseEntity<int>
{
    public string Name { get; set; } = "";

    public int Rank { get; set; }
}

/// <summary>
/// An auditable, soft-deletable entity whose audit user key is a <see cref="Guid"/>. Its key is generated by the store.
/// </summary>
public class Note : BaseAuditableDeletableEntity<int, Guid>
{
    public string Title { get; set; } = "";

    public int Rank { get; set; }
}

/// <summary>
/// An auditable, soft-deletable entity that belongs to a tenant (<see cref="ITenantEntity{TTenantKey}"/>). Used only by
/// <see cref="TenantConformanceTests{TStore}"/>; stores that don't support tenancy need not map it. Its key is
/// generated by the store.
/// </summary>
public class Invoice : BaseAuditableDeletableEntity<int, Guid>, ITenantEntity<Guid>
{
    public Guid TenantId { get; set; }

    public string Title { get; set; } = "";
}

/// <summary>
/// A tenant entity that refers to an <see cref="Invoice"/> through a foreign key that does not include
/// <c>TenantId</c>, so only the commit can stop it from pointing at another tenant's invoice. Used only by
/// <see cref="TenantConformanceTests{TStore}"/>. Its key is generated by the store.
/// </summary>
public class Payment : BaseEntity<int>, ITenantEntity<Guid>
{
    public Guid TenantId { get; set; }

    /// <summary>Gets or sets the paid invoice; the store maps it as a foreign key to <see cref="Invoice"/>.</summary>
    public int InvoiceId { get; set; }

    public decimal Amount { get; set; }
}

/// <summary>
/// An auditable, soft-deletable entity protected by optimistic concurrency (<see cref="IVersionedEntity"/>). Its key
/// is generated by the store.
/// </summary>
public class Ticket : BaseAuditableDeletableEntity<int, Guid>, IVersionedEntity
{
    public string Title { get; set; } = "";

    public long Version { get; set; }
}
